import NextAuth from "next-auth";
import { authOptions } from "../../../../lib/auth";
import { type NextRequest, NextResponse } from "next/server";

const handler = NextAuth(authOptions);

const corsHandler = async (req: NextRequest, context: any) => {
  const origin = req.headers.get("origin") || "http://localhost:8080";

  if (req.method === "OPTIONS") {
    return new NextResponse(null, {
      status: 200,
      headers: {
        "Access-Control-Allow-Origin": origin,
        "Access-Control-Allow-Methods": "GET, POST, OPTIONS, PUT, DELETE",
        "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Requested-With",
        "Access-Control-Allow-Credentials": "true",
      },
    });
  }

  // NextAuth expects the request and params
  const response = await (handler as any)(req, context);
  
  if (!response) return response;

  // Clone headers and body to a new NextResponse
  const newResponse = new NextResponse(response.body, response);
  newResponse.headers.set("Access-Control-Allow-Origin", origin);
  newResponse.headers.set("Access-Control-Allow-Credentials", "true");
  newResponse.headers.set("Access-Control-Allow-Methods", "GET, POST, OPTIONS, PUT, DELETE");
  newResponse.headers.set("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Requested-With");

  return newResponse;
};

export { corsHandler as GET, corsHandler as POST };
